/**
 * Every address in the workspace, archived projects included. An archived
 * project's address stays reserved so it can be restored under its own.
 */
export async function listTakenProjectSlugs(
  orgId: OrgId,
): Promise<readonly string[]> {
  const rows = getDb()
    .select({ slug: projects.slug })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.slug);
}

/** Every project key in the workspace, archived projects included. */
async function listTakenProjectKeys(orgId: OrgId): Promise<readonly string[]> {
  const rows = getDb()
    .select({ key: projects.key })
    .from(projects)
    .where(orgPredicate(projects.orgId, orgId))
    .all();
  return rows.map((row) => row.key);
}

/** Project keys are 2–4 characters and match `^[A-Z][A-Z0-9]*$`. */
const PROJECT_KEY_MAX = 4;

/**
 * Makes `key` unique within `taken` the way `uniqueSlug` makes an address
 * unique: append 2, 3, … and trim the front so the result never exceeds four
 * characters (`WV` → `WV2`, `TEAM` → `TEA2`).
 */
function uniqueProjectKey(key: string, taken: Iterable<string>): string {
  const used = new Set([...taken].map((value) => value.toUpperCase()));
  const cleaned = key.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, PROJECT_KEY_MAX);
  const base = /^[A-Z][A-Z0-9]{0,3}$/.test(cleaned) && cleaned.length >= 1
    ? cleaned
    : "TASK";
  if (base.length >= 2 && !used.has(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const tail = String(suffix);
    const room = PROJECT_KEY_MAX - tail.length;
    if (room < 1) continue;
    const candidate = `${base.slice(0, room)}${tail}`;
    if (!/^[A-Z][A-Z0-9]{1,3}$/.test(candidate)) continue;
    if (!used.has(candidate)) return candidate;
  }
  throw new Error(`Project key "${base}" exhausted unique suffixes`);
}

