/**
 * Refuses the write when another live project would pass the plan's project
 * quota. Archived projects do not hold a slot.
 */
async function assertProjectSlotAvailable(orgId: OrgId): Promise<void> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  const used = await projectRepo.countProjects(orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }
}

/** True when every supplied field already matches the stored project. */
function updateIsUnchanged(project: Project, input: UpdateProjectInput): boolean {
  return (
    (input.name === undefined || input.name === project.name) &&
    (input.description === undefined || input.description === project.description) &&
    (input.visibility === undefined || input.visibility === project.visibility) &&
    (input.status === undefined || input.status === project.status) &&
    (input.leadId === undefined || input.leadId === project.leadId) &&
    (input.color === undefined || input.color === project.color) &&
    (input.targetDate === undefined || input.targetDate === project.targetDate)
  );
}

