import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("./server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { registerUsageListeners, recomputeUsage } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";
import type { CreateProjectInput } from "@/schemas/project";
import type { OrgId } from "@/types/common";

function projectInput(
  orgId: OrgId,
  overrides: Partial<{ name: string; slug: string; key: string }> = {},
): CreateProjectInput {
  return {
    orgId,
    name: overrides.name ?? "Widget Works",
    slug: overrides.slug ?? "widget-works",
    key: overrides.key ?? "WID",
    description: null,
    visibility: "org",
    leadId: null,
    color: "#6366f1",
    targetDate: null,
  };
}

let cleanup: () => void;
let offUsage: () => void;
let offActivity: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  offUsage = registerUsageListeners();
  offActivity = registerActivityListeners();
});

afterAll(() => {
  offUsage();
  offActivity();
  cleanup();
});

describe("reported project bugs", () => {
  it("frees a plan slot as soon as a project is archived", async () => {
    const tenant = await createTenant("slotfree", "free");
    await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Second", slug: "second", key: "SEC" }),
    );
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: true,
    });
    const created = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Third", slug: "third", key: "THR" }),
    );
    expect(created.slug).toBe("third");
    expect(await projectRepo.countProjects(tenant.org.id)).toBe(2);
  });

  it("suffixes a colliding key, including one held by an archived project", async () => {
    const tenant = await createTenant("keycoll", "growth");
    const first = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Web Vendors", slug: "web-vendors", key: "WV" }),
    );
    expect(first.key).toBe("WV");
    const second = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Web Visitors", slug: "web-visitors", key: "WV" }),
    );
    expect(second.key).toBe("WV2");
    expect(second.key.length).toBeLessThanOrEqual(4);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: first.id,
      archiveIssues: false,
    });
    const third = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Web Velocity", slug: "web-velocity", key: "WV" }),
    );
    expect(third.key).not.toBe("WV");
    expect(third.key).not.toBe("WV2");
    expect(third.key.length).toBeLessThanOrEqual(4);
  });

  it("keeps an archived address and restores under it", async () => {
    const tenant = await createTenant("addr", "growth");
    expect(tenant.project.slug).toBe("platform");
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    const created = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Platform", slug: "platform", key: "PLAX" }),
    );
    expect(created.slug).not.toBe("platform");
    const restored = await projectService.restoreProject(
      tenant.actors.admin,
      tenant.org.id,
      tenant.project.id,
    );
    expect(restored.slug).toBe("platform");
    expect(restored.archivedAt).toBeNull();
    expect(restored.status).toBe(tenant.project.status);
  });

  it("refuses restore when the plan is full and otherwise moves the meter", async () => {
    const tenant = await createTenant("meter", "free");
    await usageRepo.recomputeUsage(tenant.org.id);
    const extra = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Second", slug: "second", key: "SEC" }),
    );
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Third", slug: "third", key: "THR" }),
    );
    const before = await usageRepo.getUsage(tenant.org.id);
    const received: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      received.push(payload);
    });
    await expect(
      projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id),
    ).rejects.toThrow(/allows 2 projects/);
    off();
    expect(received).toHaveLength(0);
    const still = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(still?.archivedAt).not.toBeNull();
    const afterRefuse = await usageRepo.getUsage(tenant.org.id);
    expect(afterRefuse.projectsUsed).toBe(before.projectsUsed);

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: extra.id,
      archiveIssues: false,
    });
    const mid = await usageRepo.getUsage(tenant.org.id);
    await projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id);
    const live = await usageRepo.getUsage(tenant.org.id);
    expect(live.projectsUsed).toBe(mid.projectsUsed + 1);
    const recounted = await recomputeUsage(tenant.org.id);
    expect(recounted.projectsUsed).toBe(live.projectsUsed);
  });

  it("refuses to restore a project that is not archived and writes no activity", async () => {
    const tenant = await createTenant("notarch", "growth");
    const before = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["project.restored"],
      limit: 20,
      cursor: null,
    });
    const received: unknown[] = [];
    const off = subscribe("project.restored", (payload) => {
      received.push(payload);
    });
    await expect(
      projectService.restoreProject(tenant.actors.admin, tenant.org.id, tenant.project.id),
    ).rejects.toThrow(/not archived/);
    off();
    expect(received).toHaveLength(0);
    const after = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["project.restored"],
      limit: 20,
      cursor: null,
    });
    expect(after.total).toBe(before.total);
    const stored = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(stored?.archivedAt).toBeNull();
  });

  it("persists status, blocks new issues, and refuses completion while issues are open", async () => {
    const tenant = await createTenant("status", "growth");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Still open" }),
    );

    await expect(
      projectService.updateProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        status: "completed",
      }),
    ).rejects.toThrow(/open issues/);
    const unchanged = await projectRepo.findProjectById(tenant.org.id, tenant.project.id);
    expect(unchanged?.status).toBe("active");

    const paused = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "paused",
    });
    expect(paused.status).toBe("paused");

    const filtered = await projectRepo.listProjects({
      orgId: tenant.org.id,
      status: "paused",
      limit: 20,
      cursor: null,
    });
    expect(filtered.items.map((row) => row.id)).toContain(tenant.project.id);
    const active = await projectRepo.listProjects({
      orgId: tenant.org.id,
      status: "active",
      limit: 20,
      cursor: null,
    });
    expect(active.items.map((row) => row.id)).not.toContain(tenant.project.id);

    const received: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      received.push(payload);
    });
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: "Should not land" }),
      ),
    ).rejects.toThrow(/paused/);
    off();
    expect(received).toHaveLength(0);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(1);

    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      status: "done",
    });
    const completed = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "completed",
    });
    expect(completed.status).toBe("completed");

    const again = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      name: completed.name,
      description: completed.description,
      visibility: completed.visibility,
      status: "completed",
      leadId: completed.leadId,
      color: completed.color,
      targetDate: completed.targetDate,
    });
    expect(again.updatedAt).toBe(completed.updatedAt);
    expect(again.status).toBe("completed");

    const reactivated = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "active",
    });
    expect(reactivated.status).toBe("active");

    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      archiveIssues: false,
    });
    await expect(
      projectService.updateProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        status: "paused",
      }),
    ).rejects.toThrow(/archived/);
  });

  it("suffixes a four-character key without exceeding four characters", async () => {
    const tenant = await createTenant("keytrim", "growth");
    const first = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Team", slug: "team", key: "TEAM" }),
    );
    expect(first.key).toBe("TEAM");
    const second = await projectService.createProject(
      tenant.actors.member,
      projectInput(tenant.org.id, { name: "Team Two", slug: "team-two", key: "TEAM" }),
    );
    expect(second.key).toBe("TEA2");
    expect(second.key.length).toBeLessThanOrEqual(4);
  });

  it("lets a completed project with only done, canceled, and archived issues complete", async () => {
    const tenant = await createTenant("closedok", "growth");
    const done = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Done one" }),
    );
    const canceled = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Canceled one" }),
    );
    const archived = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Archived one" }),
    );
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: done.id,
      status: "done",
    });
    await issueService.changeIssueStatus(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: canceled.id,
      status: "canceled",
    });
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, archived.id);

    const completed = await projectService.updateProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: tenant.project.id,
      status: "completed",
    });
    expect(completed.status).toBe("completed");
  });
});

